"""Render the benchmark JSON as docs/EVALUATION_REPORT.md. Pure formatting: no number is computed or invented here."""
from __future__ import annotations

from pathlib import Path

from evaluation.metrics.stats import pct


def _ms(v) -> str:
    return "n/a" if v is None else f"{v:,.0f} ms"


def _f(v, d=2) -> str:
    return "n/a" if v is None else f"{v:,.{d}f}"


def rows_opt(_opt):
    f2, pc = _f, pct
    return [
        ("instances (optimal plans / infeasible)", lambda d: f"{d['instances']} ({d['optimal_plans']} / {d['infeasible']})"),
        ("lowest-sticker-price choice invalid (breaks MOQ / capacity / quality floor)", lambda d: str(d["price_only_choice_invalid"])),
        ("orders only a split plan can serve", lambda d: str(d["orders_only_a_multi_supplier_plan_can_serve"])),
        ("compared with `cheapest*` (of which split)", lambda d: f"{d['compared_with_constraint_aware_cheapest']} ({d['split_orders']})"),
        ("mean purchase-cost premium vs `cheapest*`", lambda d: pc(d["mean_purchase_cost_premium"], 2)),
        ("mean risk-score change (negative = safer)", lambda d: f2(d["mean_risk_score_change"], 3)),
        ("mean weighted lead-time change (days)", lambda d: f2(d["mean_weighted_lead_time_change_days"])),
        ("mean change in slowest supplier's lead time (days)", lambda d: f2(d["mean_slowest_supplier_lead_change_days"])),
        ("change in P(majority of units never arrive), all plans", lambda d: f2(d["mean_change_in_prob_majority_of_units_lost"], 4)),
        ("change in P(majority never arrive), split plans only", lambda d: f2(d["split_orders_mean_change_in_prob_majority_lost"], 4)),
        ("lead time exceeds stock cover: `cheapest*` / optimiser", lambda d: f"{d['lead_time_exceeds_cover_cheapest_vs_optimizer'][0]} / {d['lead_time_exceeds_cover_cheapest_vs_optimizer'][1]}"),
    ]


def write_markdown(p: dict, path: Path) -> None:
    s, ar, llm, perf, biz = p["summary"], p["summary"]["agent_reliability"], p["summary"]["llm"], p["summary"]["performance"], p["summary"]["business"]
    fa, sp, inv, opt, live = p["forecast_accuracy"], p["stockout_prediction"], p["inventory_simulation"], p["optimizer_vs_cheapest"], p.get("live_llm")
    L: list[str] = []
    L += ["# Evaluation report", "",
          f"> Generated by `python -m evaluation.runner benchmark` on {p['generated_at']} (run time {p['duration_s']} s). Every number below was produced by that run; "
          "nothing is hand-written. Scenarios use **synthetic data** and a **scripted LLM** (so the run is reproducible and offline) unless a section says it used the real local model.", "",
          "## 1. Scenario benchmark", "",
          f"**{s['passed']} / {s['scenarios']} scenarios passed** ({pct(s['task_success_rate'])}); {s['failed']} failed.", "",
          "| Category | Scenarios | Passed | Rate |", "|---|---:|---:|---:|"]
    L += [f"| {k} | {v['n']} | {v['passed']} | {pct(v['rate'])} |" for k, v in s["by_category"].items()]
    failed = [r for r in p["scenarios"] if not r["passed"]]
    if failed:
        L += ["", "### Failed scenarios", "", "| Scenario | Problems |", "|---|---|"] + [f"| {r['id']} | {'; '.join(r['problems'])[:300]} |" for r in failed]
    L += ["", "Every scenario also checks universal invariants: no dangling pending orders, no order without human approval, no duplicate orders, no non-positive "
          "quantity/price, audit hash chain intact, approved orders pass policy, no unexpected exception.", "",
          "## 2. Agent reliability", "", "| Metric | Value |", "|---|---:|",
          f"| task success rate | {pct(ar['task_success_rate'])} |", f"| tool (node) failure rate | {pct(ar['tool_failure_rate'], 2)} (includes deliberately injected crashes) |",
          f"| fallback rate (runs that used a deterministic fallback) | {pct(ar['fallback_rate'])} |",
          f"| recovery rate ({ar['fault_scenarios']} fault-injected scenarios handled as expected) | {pct(ar['recovery_rate'])} |",
          f"| human escalation rate (runs reaching the approval gate) | {pct(ar['human_escalation_rate'])} |", "",
          "## 3. LLM quality", "", "### 3a. Scripted model (the 114-scenario benchmark)", "", "| Metric | Value |", "|---|---:|",
          f"| model calls | {llm['calls']:,} |", f"| structured-output validity (ok or regex-repaired) | {pct(llm['structured_output_validity'])} |",
          f"| invalid outputs rejected | {llm['invalid_outputs']} |", f"| errors / timeouts | {llm['errors_or_timeouts']} |",
          f"| tokens in / out (estimated) | {llm['tokens_in']:,} / {llm['tokens_out']:,} |", f"| tokens per workflow | {_f(llm['tokens_per_workflow'], 0)} |",
          f"| cloud-equivalent cost per workflow | ${_f(llm['cloud_equivalent_cost_per_workflow_usd'], 6)} |",
          f"| cloud-equivalent cost per successful procurement line | ${_f(llm['cloud_equivalent_cost_per_successful_procurement_usd'], 6)} |", "",
          f"_{llm['note']}_", ""]
    L += ["### 3b. Real local model (live sample)", ""]
    if live and live.get("available"):
        L += [f"Model `{live['model']}`, {live['workflows']} workflow(s), {live['llm_calls']} calls.", "", "| Metric | Value |", "|---|---:|",
              f"| structured-output validity | {pct(live['structured_output_validity'])} |", f"| groundedness (every SKU named exists) | {pct(live['groundedness'])} |",
              f"| hallucination rate (names a non-existent SKU) | {pct(live['hallucination_rate'])} |",
              f"| instruction following (<= 4 sentences, JSON schema) | {pct(live['instruction_following_rate'])} |",
              f"| consistency (identical prompts -> valid replies naming the same SKUs) | {pct(live['consistency'])} over {live['consistency_pairs']} repeated prompt(s) |",
              f"| call latency p50 / p95 / p99 | {_ms(live['call_latency']['p50_ms'])} / {_ms(live['call_latency']['p95_ms'])} / {_ms(live['call_latency']['p99_ms'])} |",
              f"| workflow latency p50 / p95 | {_ms(live['workflow_latency']['p50_ms'])} / {_ms(live['workflow_latency']['p95_ms'])} |",
              f"| tokens in / out | {live['tokens_in']:,} / {live['tokens_out']:,} |", f"| TTFT | {live['ttft']} |", ""]
        if live["hallucinated_examples"]:
            L += [f"Hallucinated identifiers observed: `{live['hallucinated_examples']}`", ""]
        L += ["Small sample: treat these as indicative, not statistically conclusive.", ""]
    else:
        L += [f"Not run ({(live or {}).get('reason', 'use --live-llm N to include it')}).", ""]
    wl = perf["workflow_latency"]
    L += ["## 4. Performance (scripted model, local SQLite, single process)", "", "| Metric | Value |", "|---|---:|",
          f"| workflow latency P50 | {_ms(wl['p50_ms'])} |", f"| workflow latency P95 | {_ms(wl['p95_ms'])} |", f"| workflow latency P99 | {_ms(wl['p99_ms'])} |",
          f"| max | {_ms(wl['max_ms'])} |", "", "Per-node time per workflow (sum of that node's executions):", "", "| Node | runs | P50 | P95 | P99 |", "|---|---:|---:|---:|---:|"]
    L += [f"| {k} | {v['n']} | {_ms(v['p50_ms'])} | {_ms(v['p95_ms'])} | {_ms(v['p99_ms'])} |" for k, v in perf["per_node_ms"].items()]
    L += ["", "The latency of a real run is dominated by the model (tens of seconds per call on a CPU-only Ollama); see 3b.", "",
          "## 5. Forecasting (synthetic series with a known generating process)", "",
          f"{fa['series']} series, {fa['history_days']} days of history, {fa['horizon_days']}-day out-of-sample horizon.", "", "| Metric | Engine (best model by backtest) | Naive: mean of last 7 days |", "|---|---:|---:|",
          f"| MAE | {_f(fa['engine']['mae'])} | {_f(fa['naive_last7_mean']['mae'])} |", f"| RMSE | {_f(fa['engine']['rmse'])} | {_f(fa['naive_last7_mean']['rmse'])} |",
          f"| MAPE (only where defined) | {_f(fa['engine']['mape'])}% | {_f(fa['naive_last7_mean']['mape'])}% |", f"| WAPE | {pct(fa['engine']['wape'])} | {pct(fa['naive_last7_mean']['wape'])} |", "",
          f"RMSE improvement vs naive: **{pct(fa['rmse_improvement_vs_naive'])}**. MAPE was defined for {fa['mape_defined_for']}/{fa['series']} series. Models chosen: {fa['methods_chosen']}.", "",
          "### Stock-out prediction accuracy", "",
          f"{sp['cases']} synthetic situations; ground truth = does the TRUE demand process exhaust the stock within the lead time (actual stock-out rate {pct(sp['actual_stockout_rate'])}).", "",
          "| | Risk engine (HIGH/CRITICAL) | Legacy static reorder-point rule |", "|---|---:|---:|"]
    e, o = sp["risk_engine_high_or_critical"], sp["legacy_static_rule"]
    L += [f"| precision | {pct(e['precision'])} | {pct(o['precision'])} |", f"| recall | {pct(e['recall'])} | {pct(o['recall'])} |", f"| accuracy | {pct(e['accuracy'])} | {pct(o['accuracy'])} |",
          f"| F1 | {_f(e['f1'], 3)} | {_f(o['f1'], 3)} |", f"| TP / FP / FN / TN | {e['tp']}/{e['fp']}/{e['fn']}/{e['tn']} | {o['tp']}/{o['fp']}/{o['fn']}/{o['tn']} |", "",
          "### Inventory simulation (stock-out reduction)", "",
          f"{inv['skus']} SKUs x {inv['days']} days. Same demand, same suppliers, same random delivery delays; only the ordering policy differs.", "",
          "| | Static reorder point | Predictive engine |", "|---|---:|---:|"]
    a, b = inv["static_reorder_point"], inv["predictive_engine"]
    L += [f"| stock-out days per SKU | {_f(a['stockout_days_per_sku'])} | {_f(b['stockout_days_per_sku'])} |", f"| SKUs with any stock-out | {a['skus_with_any_stockout']} | {b['skus_with_any_stockout']} |",
          f"| orders per SKU | {_f(a['orders_per_sku'])} | {_f(b['orders_per_sku'])} |", f"| average stock (units) | {_f(a['avg_stock_units'], 0)} | {_f(b['avg_stock_units'], 0)} |",
          f"| purchase spend | ${_f(a['purchase_cost'], 0)} | ${_f(b['purchase_cost'], 0)} |", "",
          f"Stock-out-day reduction: **{pct(inv['stockout_day_reduction'])}**. Note the trade-off visible in the spend and order-count rows. These are simulated results, not field results.", "",
          "## 6. Procurement", "", "### Scenario benchmark (approved runs)", "", "| Metric | Value |", "|---|---:|",
          f"| approved runs | {biz['approved_runs']} ({biz['outlier_runs_excluded_from_money']} stress outlier excluded from the money rows) |", f"| order value | ${_f(biz['order_value_usd'], 0)} |", f"| savings vs average quote | ${_f(biz['procurement_savings_usd'], 0)} ({pct(biz['savings_vs_avg_quote_pct'])}) |",
          f"| average supplier lead time (qty-weighted) | {_f(biz['avg_supplier_lead_time_days'])} days |", f"| average supplier reliability score | {_f(biz['avg_supplier_reliability_score'], 1)} |",
          f"| human approval rate | {pct(biz['human_approval_rate'])} |", f"| re-source rate | {pct(biz['re_source_rate'])} |", f"| split-order lines | {biz['split_order_lines']} |",
          f"| lines blocked by policy | {biz['policy_blocked_lines']} |", "", f"_{biz['reviewer_note']}_", "",
          "### Optimiser vs price-only baselines (random synthetic quote sets)", "",
          "`naive` = lowest sticker price, constraints ignored. `cheapest*` = lowest price among suppliers that satisfy every hard constraint (quality / reliability floors, MOQ, capacity). "
          "Resilience: each supplier independently fails to deliver with probability (1 - reliability); all failure combinations are enumerated exactly.", "",
          "| Metric | Default (70 % supplier-share cap) | Share cap off (100 %) |", "|---|---:|---:|",
          *[f"| {label} | {fa_(d)} | {fa_(n)} |" for label, fa_ in rows_opt(opt)
            for d, n in [(opt["default_70pct_share_cap"], opt["no_share_cap"])]], "",
          "Reading: the optimiser always respects hard constraints (the price-only choice is invalid in the first row's count of instances). Against a constraint-aware cheapest-price "
          "baseline, the default diversification cap buys a smaller probability of losing most of an order at a purchase-cost premium; it is a policy choice, configurable via "
          "`SCM_OPTIMIZER__MAX_SUPPLIER_SHARE`.", "",
          "## 7. Reproduce", "", "```bash", "python -m evaluation.runner benchmark --live-llm 3 --report docs/EVALUATION_REPORT.md", "python -m evaluation.runner chaos", "```", ""]
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text("\n".join(L), encoding="utf-8")
